/**
 * @name Zip Slip vulnerability
 * @description Extracting files from a malicious zip archive without validating the destination path can allow overwriting arbitrary files.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Names of files in a zip archive
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("namelist").getACall() and
      source = call
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("infolist").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File opening or writing operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() and
      sink = call.getArg(_)
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip: file path from zip archive used in file operation from $@.", source.getNode(), "archive content"
